<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<title>Galaga</title>
<style>
  html,body{margin:0;height:100%;background:#000;overflow:hidden}
  #wrap{display:flex;align-items:center;justify-content:center;height:100%}
  canvas{image-rendering:pixelated;image-rendering:crisp-edges}
</style>
</head>
<body>
<div id="wrap"><canvas id="game" width="224" height="288"></canvas></div>
<script>
'use strict';
/* =========================================================
   GALAGA clone - single-file, no external resources.
   Logical playfield 224x288, fixed-timestep update, canvas render.
   ========================================================= */

// ---------- screen / loop ----------
const W=224,H=288,DT=1000/60;
const canvas=document.getElementById('game');
const ctx=canvas.getContext('2d');
ctx.imageSmoothingEnabled=false;
function fit(){const s=Math.max(1,Math.min(Math.floor(innerWidth/W),Math.floor(innerHeight/H)));canvas.style.width=(W*s)+'px';canvas.style.height=(H*s)+'px';}
addEventListener('resize',fit);fit();

// ---------- palette + sprites (pixel data) ----------
const PAL={W:'#ffffff',B:'#3b5bff',C:'#3fd0ff',Y:'#ffd233',R:'#ff3322',G:'#22cc22',P:'#9933ff'};
const PLAYER=[
".......CC.......",
".......CC.......",
".......CC.......",
"......CCCC......",
"......CCCC......",
"B.....CCCC.....B",
"BB....CCCC....BB",
".BB...CCCC...BB.",
".BBBB.CCCC.BBBB.",
"..BBBBCCCCBBBB..",
"..BBBBCCCCBBBB..",
"...BBBBBBBBBB...",
"....BBBBBBBB....",
".....BBBBBB.....",
"......BBBB......",
"................"];
const ZAKO0=[
"................",
"...YY......YY...",
"...YY......YY...",
"....YY....YY....",
".....BBBBBB.....",
"....BBBBBBBB....",
"....BBYYYYBB....",
".....BYYYYB.....",
"......YYYY......",
"................"];
const ZAKO1=[
"................",
"................",
".....BBBBBB.....",
"....BBBBBBBB....",
"....BBYYYYBB....",
".....BYYYYB.....",
"...YY.YYYY.YY...",
"...YY......YY...",
"................"];
const GOEI0=[
"................",
".RR..........RR.",
".RRR........RRR.",
"..RRR......RRR..",
"...RRRRRRRRRR...",
"...RR.BBBB.RR...",
"....R.BBBB.R....",
".....BBBBBB.....",
"......B..B......",
"................"];
const GOEI1=[
"................",
"....RRRRRRRR....",
"...RR.BBBB.RR...",
".RRRR.BBBB.RRRR.",
".RRR..BBBB..RRR.",
"..RR..B..B..RR..",
"................"];
const BOSS0=[
"................",
"....GG....GG....",
"....GG....GG....",
".....GG..GG.....",
"..GG.GGGGGG.GG..",
"..GG.GGGGGG.GG..",
"...GG.GGGG.GG...",
"....GGGGGGGG....",
"....GGYYYYGG....",
".....YYYYYY.....",
"......YYYY......",
".......YY......."];
const BOSS1=[
"................",
"................",
".....GG..GG.....",
"..GG.GGGGGG.GG..",
"..GGGGGGGGGGGG..",
"...GG.GGGG.GG...",
"....GGGGGGGG....",
"....GGYYYYGG....",
".....YYYYYY.....",
"......YYYY......",
"................"];
function makeSprite(rows){const w=rows[0].length,h=rows.length;const c=document.createElement('canvas');c.width=w;c.height=h;const x=c.getContext('2d');for(let j=0;j<h;j++)for(let i=0;i<w;i++){const ch=rows[j][i];if(ch!=='.'){x.fillStyle=PAL[ch];x.fillRect(i,j,1,1);}}return c;}
const SP={
  player:makeSprite(PLAYER),
  captured:makeSprite(PLAYER.map(r=>r.replace(/B/g,'R').replace(/C/g,'W'))),
  zako:[makeSprite(ZAKO0),makeSprite(ZAKO1)],
  goei:[makeSprite(GOEI0),makeSprite(GOEI1)],
  boss:[makeSprite(BOSS0),makeSprite(BOSS1)],
  bossHit:[makeSprite(BOSS0.map(r=>r.replace(/G/g,'P'))),makeSprite(BOSS1.map(r=>r.replace(/G/g,'P')))]
};
function drawSprite(sp,cx,cy){ctx.drawImage(sp,Math.round(cx-sp.width/2),Math.round(cy-sp.height/2));}

// ---------- audio (all synthesized) ----------
let actx=null,muted=false;
function ensureAudio(){try{if(!actx)actx=new (window.AudioContext||window.webkitAudioContext)();if(actx.state==='suspended')actx.resume();}catch(e){}}
function tone(f0,f1,dur,type,vol,delay){if(!actx||muted)return;const t=actx.currentTime+(delay||0);const o=actx.createOscillator(),g=actx.createGain();o.type=type;o.frequency.setValueAtTime(f0,t);o.frequency.exponentialRampToValueAtTime(Math.max(f1,1),t+dur);g.gain.setValueAtTime(vol,t);g.gain.exponentialRampToValueAtTime(0.001,t+dur);o.connect(g).connect(actx.destination);o.start(t);o.stop(t+dur+0.02);}
function noiseBurst(dur,vol,freq,delay){if(!actx||muted)return;const t=actx.currentTime+(delay||0);const n=Math.max(1,Math.floor(actx.sampleRate*dur));const buf=actx.createBuffer(1,n,actx.sampleRate);const d=buf.getChannelData(0);for(let i=0;i<n;i++)d[i]=Math.random()*2-1;const src=actx.createBufferSource();src.buffer=buf;const f=actx.createBiquadFilter();f.type='lowpass';f.frequency.value=freq;const g=actx.createGain();g.gain.setValueAtTime(vol,t);g.gain.exponentialRampToValueAtTime(0.001,t+dur);src.connect(f).connect(g).connect(actx.destination);src.start(t);}
const sShoot=()=>tone(1050,180,0.09,'square',0.12);
const sHit=()=>noiseBurst(0.08,0.2,4000);
const sDie=()=>{noiseBurst(0.25,0.25,2500);tone(420,70,0.28,'sawtooth',0.14);};
const sBossHit=()=>{tone(220,60,0.22,'square',0.18);noiseBurst(0.1,0.18,1500);};
const sPlayerDie=()=>{noiseBurst(0.6,0.35,900);tone(300,40,0.5,'sawtooth',0.2);};
const sCapture=()=>tone(150,900,0.6,'sine',0.15);
const sDock=()=>{tone(500,1200,0.15,'square',0.12);tone(700,1500,0.15,'square',0.1,0.08);};
const sJingle=()=>{tone(392,392,0.12,'square',0.12,0);tone(523,523,0.12,'square',0.12,0.13);tone(659,659,0.12,'square',0.12,0.26);tone(784,784,0.2,'square',0.14,0.39);};
let tractorNodes=null;
function startTractor(){if(!actx||muted||tractorNodes)return;const o=actx.createOscillator(),g=actx.createGain(),lfo=actx.createOscillator(),lg=actx.createGain();o.type='sawtooth';o.frequency.value=170;lfo.type='sine';lfo.frequency.value=9;lg.gain.value=70;lfo.connect(lg);lg.connect(o.frequency);g.gain.value=0.05;o.connect(g);g.connect(actx.destination);o.start();lfo.start();tractorNodes={o,lfo};}
function stopTractor(){if(tractorNodes){try{tractorNodes.o.stop();tractorNodes.lfo.stop();}catch(e){}tractorNodes=null;}}

// ---------- starfield ----------
const stars=[];
for(let i=0;i<70;i++)stars.push({x:Math.random()*W,y:Math.random()*H,s:0.25+Math.random()*1.1,c:['#ffffff','#8888ff','#ff8888','#88ffff','#ffff88'][i%5],ph:Math.random()*6.28});
function updateStars(){for(const s of stars){s.y+=s.s;if(s.y>=H){s.y-=H;s.x=Math.random()*W;}}}

// ---------- game state ----------
let state='title',tick=0,paused=false;
let score=0,high=0,stage=1,lives=3,nextExtra=20000;
try{high=parseInt(localStorage.getItem('galagaHigh')||'0',10)||0;}catch(e){high=0;}
let shots=0,hits=0;
let enemies=[],pShots=[],eShots=[],expls=[],freed=[];
let readyTimer=0,deathTimer=0,clearTimer=0,introTimer=0,resTimer=0;
let diveTimer=120,allEntered=false,sway=0,breath=1;
let challenging=false,chalHits=0,chalWaves=null;
const player={x:112,y:252,alive:false,dual:false,capturePull:false,capturingBoss:null};

// ---------- input ----------
const keys={};
addEventListener('keydown',e=>{
  ensureAudio();
  if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown',' ','Enter'].includes(e.key))e.preventDefault();
  if(e.repeat)return;
  keys[e.key]=true;
  if(e.key==='Enter'&&state==='title')startGame();
  if(e.key===' '&&state==='play')tryFire();
  if(e.key==='p'||e.key==='P')paused=!paused;
  if(e.key==='m'||e.key==='M')muted=!muted;
});
addEventListener('keyup',e=>{keys[e.key]=false;});

// ---------- helpers ----------
function addScore(n){score+=n;if(score>nextExtra){lives++;nextExtra+=70000;}if(score>high){high=score;try{localStorage.setItem('galagaHigh',String(high));}catch(e){}}}
function text(s,x,y,c,size,align){ctx.font='bold '+(size||8)+'px monospace';ctx.textAlign=align||'left';ctx.fillStyle=c||'#fff';ctx.fillText(s,x,y);}
function overlap(ax,ay,ahw,ahh,bx,by,bhw,bhh){return Math.abs(ax-bx)<ahw+bhw&&Math.abs(ay-by)<ahh+bhh;}
function bez(p0,p1,p2,p3,t){const u=1-t;return u*u*u*p0+3*u*u*t*p1+3*u*t*t*p2+t*t*t*p3;}

// ---------- explosions (frame-animated particles) ----------
function boom(x,y,big){const cols=['#ffffff','#ff8833','#ff3322','#3fd0ff','#ffd233'];const n=big?22:12;for(let i=0;i<n;i++){const a=Math.random()*6.283,sp=(big?1:0.6)+Math.random()*(big?2.4:1.4);expls.push({x,y,vx:Math.cos(a)*sp,vy:Math.sin(a)*sp,life:20+Math.random()*(big?24:14),c:cols[i%5]});}}
function updateExpls(){for(let i=expls.length-1;i>=0;i--){const p=expls[i];p.x+=p.vx;p.y+=p.vy;p.vx*=0.95;p.vy*=0.95;if(--p.life<=0)expls.splice(i,1);}}
function drawExpls(){for(const p of expls){ctx.fillStyle=(tick%4<2)?p.c:'#ffffff';ctx.fillRect(Math.round(p.x)-1,Math.round(p.y)-1,2,2);}}

// ---------- formation ----------
const ENTRY=[
 {sx:-30,sy:70,c1:[110,-25],c2:[185,120]},
 {sx:254,sy:70,c1:[114,-25],c2:[39,120]},
 {sx:-30,sy:210,c1:[120,270],c2:[155,15]},
 {sx:254,sy:210,c1:[104,270],c2:[69,15]}
];
function formPos(e){
  const cx=112,cy=90;
  return {x:cx+(e.slotX-cx)*breath+sway,y:cy+(e.slotY-cy)*breath};
}
function buildStage(){
  enemies=[];pShots=[];eShots=[];freed=[];allEntered=false;diveTimer=120;
  const slots=[];
  for(let r=0;r<2;r++)for(let c=0;c<10;c++)slots.push({type:'zako',x:12+c*20,y:104+r*20});
  for(let r=0;r<2;r++)for(let c=0;c<8;c++)slots.push({type:'goei',x:28+c*24,y:64+r*20});
  for(let c=2;c<=5;c++)slots.push({type:'boss',x:28+c*24,y:44});
  slots.forEach((s,i)=>{
    const g=Math.floor(i/4),ep=ENTRY[g%ENTRY.length];
    enemies.push({type:s.type,slotX:s.x,slotY:s.y,x:ep.sx,y:ep.sy,state:'enter',
      t:0,dur:210,delay:g*45+(i%4)*7,age:0,hp:s.type==='boss'?2:1,damaged:false,
      escorts:null,captive:null,angle:Math.PI/2,speed:0,fireTimer:60+Math.random()*90,
      beam:false,beamTimer:0,dived:false});
  });
}
// challenging-stage looping path
function chalPos(t,w){return{
  x:112+105*Math.sin(t*Math.PI*4+w*0.8),
  y:-26+t*350+18*Math.sin(t*Math.PI*8+w)
};}
function buildChallenging(){
  enemies=[];pShots=[];eShots=[];freed=[];chalHits=0;
  chalWaves=[];
  const types=['zako','goei','boss','goei','zako','boss','goei','zako'];
  for(let w=0;w<5;w++){chalWaves.push({dead:0,exit:0,bonus:false});
    for(let i=0;i<8;i++){
      enemies.push({type:types[i],x:-40,y:-40,state:'chal',wave:w,idx:i,t:-1,
        delay:w*220+i*11,age:0,hp:types[i]==='boss'?2:1,damaged:false,captive:null,
        escorts:null,beam:false,fireTimer:0,slotX:0,slotY:0,angle:Math.PI/2,speed:0,dur:340});
    }
  }
}

// ---------- game flow ----------
function startGame(){score=0;lives=3;nextExtra=20000;shots=0;hits=0;stage=1;beginStage();}
function beginStage(){
  challenging=(stage===3||(stage-3)%4===0&&stage>=3);
  enemies=[];pShots=[];eShots=[];freed=[];expls=[];stopTractor();
  player.x=112;player.y=252;player.alive=true;player.dual=false;player.capturePull=false;player.capturingBoss=null;
  readyTimer=90;deathTimer=0;clearTimer=0;
  if(challenging)buildChallenging();else buildStage();
  state='stageIntro';introTimer=challenging?170:120;sJingle();
}
function nextStage(){stage++;beginStage();}

// ---------- firing ----------
function tryFire(){
  if(!player.alive||readyTimer>0||deathTimer>0||player.capturePull)return;
  const cap=player.dual?4:2;
  if(pShots.length>=cap)return;
  pShots.push({x:player.x-(player.dual?8:0),y:player.y-10});
  if(player.dual)pShots.push({x:player.x+8,y:player.y-10});
  shots+=player.dual?2:1;sShoot();
}
function enemyShoot(e,spd){
  const dx=player.x-e.x,dy=player.y-e.y,d=Math.hypot(dx,dy)||1;
  eShots.push({x:e.x,y:e.y+6,vx:dx/d*spd,vy:dy/d*spd});
}

// ---------- enemy update ----------
function pickDiver(){
  const pool=enemies.filter(e=>e.state==='form');
  if(!pool.length)return null;return pool[Math.floor(Math.random()*pool.length)];
}
function startDive(e,beam){
  e.state='dive';e.dived=true;e.speed=0.6;e.angle=Math.PI/2+(Math.random()-0.5)*0.9;
  e.fireTimer=25+Math.random()*40;e.bullets=(stage>4?4:3);e.beamTarget=!!beam;
  if(beam)e.beamStopY=95+Math.random()*45;
  if(e.type==='boss'){
    e.escorts=[];
    if(!beam&&Math.random()<0.55){
      const pool=enemies.filter(x=>x.state==='form'&&x.type==='goei');
      const n=Math.min(pool.length,Math.random()<0.5?1:2);
      for(let i=0;i<n;i++){const g=pool.splice(Math.floor(Math.random()*pool.length),1)[0];
        startDive(g,false);g.escortOf=e;e.escorts.push(g);}
    }
    if(e.captive){e.captive.state='follow';}
  }
}
function updateEnemies(){
  // formation sway / breathing
  const entered=enemies.filter(e=>e.state!=='enter').length;
  allEntered=enemies.length>0&&entered===enemies.length;
  if(!challenging){
    if(!allEntered)sway=Math.sin(tick*0.02)*12;
    else{sway=Math.sin(tick*0.01)*4;breath=1+0.12*Math.sin(tick*0.015);}
  }
  const maxDivers=Math.min(2+Math.floor(stage/2),8);
  if(readyTimer<=0&&deathTimer<=0&&!challenging){
    if(--diveTimer<=0){
      diveTimer=Math.max(45,190-stage*14)*(0.6+Math.random()*0.8);
      const divers=enemies.filter(e=>e.state==='dive'||e.state==='beam').length;
      if(divers<maxDivers){
        const e=pickDiver();
        if(e){
          const wantBeam=e.type==='boss'&&stage>=2&&!e.captive&&Math.random()<0.25+stage*0.05&&
                         !enemies.some(x=>x.state==='beam');
          startDive(e,wantBeam);
        }
      }
    }
  }
  for(let i=enemies.length-1;i>=0;i--){
    const e=enemies[i];
    e.age++;
    if(e.state==='enter'){
      if(e.age<e.delay){continue;}
      e.t=Math.min(1,(e.age-e.delay)/e.dur);
      const ep=ENTRY[Math.floor(e.slotX===0?0:0)];
      // entry path chosen by group parity stored implicitly: recompute from delay group
      const g=Math.floor(e.delay/45),path=ENTRY[g%ENTRY.length];
      e.x=bez(path.sx,path.c1[0],path.c2[0],e.slotX,e.t);
      e.y=bez(path.sy,path.c1[1],path.c2[1],e.slotY,e.t);
      if(e.t>=1){e.state='form';}
      if(Math.random()<0.004)enemyShoot(e,1.8);
    }
    else if(e.state==='form'){
      const p=formPos(e);e.x=p.x;e.y=p.y;
      if(e.captive){updateCaptive(e.captive,e);}
    }
    else if(e.state==='chal'){
      if(e.age<e.delay)continue;
      e.t=(e.age-e.delay)/340;
      const p=chalPos(e.t,e.wave);e.x=p.x;e.y=p.y;
      if(e.t>1.2){ // exited
        enemies.splice(i,1);
        const w=chalWaves[e.wave];w.exit++;
        if(w.dead+w.exit===8&&!w.bonus){w.bonus=true;}
        continue;
      }
    }
    else if(e.state==='dive'){
      const maxSp=1.7+Math.min(stage*0.12,1.3);
      e.speed=Math.min(maxSp,e.speed+0.035);
      const want=Math.atan2(player.y-e.y,player.x-e.x);
      let d=want-e.angle;while(d>Math.PI)d-=2*Math.PI;while(d<-Math.PI)d+=2*Math.PI;
      const turn=0.028+Math.min(stage*0.004,0.05);
      e.angle+=Math.max(-turn,Math.min(turn,d));
      e.x+=Math.cos(e.angle)*e.speed;e.y+=Math.sin(e.angle)*e.speed;
      if(e.beamTarget&&e.y>=e.beamStopY){e.state='beam';e.beamTimer=300;e.speed=0;startTractor();}
      if(--e.fireTimer<=0&&e.bullets>0&&player.alive){e.bullets--;enemyShoot(e,2+stage*0.08);e.fireTimer=30+Math.random()*45;}
      if(e.y>H+16){e.y=-16;e.x=Math.max(16,Math.min(208,e.x));e.state='return';e.angle=-Math.PI/2;}
      if(e.captive)updateCaptive(e.captive,e);
    }
    else if(e.state==='beam'){
      e.x+=Math.sin(tick*0.05)*0.7;
      if(--e.beamTimer<=0){e.state='return';stopTractor();if(e.captive)e.captive.state='follow';}
      if(e.captive)updateCaptive(e.captive,e);
    }
    else if(e.state==='return'){
      const p=formPos(e);
      const dx=p.x-e.x,dy=p.y-e.y,d=Math.hypot(dx,dy);
      if(d<2){e.state='form';}
      else{e.x+=dx/d*1.6;e.y+=dy/d*1.6;}
      if(e.captive)updateCaptive(e.captive,e);
    }
  }
  if(tractorNodes&&!enemies.some(e=>e.state==='beam'))stopTractor();
}
function updateCaptive(c,boss){
  const tx=boss.x+(boss.state==='form'?0:12),ty=boss.y-14;
  c.x+=(tx-c.x)*0.12;c.y+=(ty-c.y)*0.12;
  if((boss.state==='dive'||boss.state==='beam')&&--c.fireTimer<=0&&player.alive){
    c.fireTimer=80+Math.random()*60;enemyShoot({x:c.x,y:c.y},2.2);
  }
}

// ---------- tractor beam ----------
function beamHalf(e){return 5+(e.y-40)*0.22;}
function updateBeamCapture(){
  if(!player.alive||readyTimer>0||deathTimer>0||player.capturePull)return;
  for(const e of enemies){
    if(e.state!=='beam')continue;
    const hw=beamHalf(e);
    if(player.y>e.y&&Math.abs(player.x-e.x)<hw){
      if(player.dual){ // capture one half of dual fighter
        const side=player.x<e.x?-8:8;
        boom(player.x+side,player.y,true);
        player.dual=false;
        e.captive={x:player.x+side,y:player.y,state:'follow',fireTimer:90};
        sCapture();
      }else{
        player.capturePull=true;player.capturingBoss=e;sCapture();
      }
      break;
    }
  }
}
function drawBeam(e){
  const hw=beamHalf(e);
  for(let y=e.y+8;y<H-14;y++){
    const f=(y-e.y)/(H-14-e.y),w=4+(hw-4)*f;
    const band=((y+tick*2)%14)<7;
    ctx.fillStyle=band?'rgba(60,120,255,0.35)':'rgba(30,70,220,0.22)';
    ctx.fillRect(Math.round(e.x-w),y,Math.round(2*w),1);
    ctx.fillStyle='#3fd0ff';
    ctx.fillRect(Math.round(e.x-w),y,1,1);ctx.fillRect(Math.round(e.x+w),y,1,1);
  }
}

// ---------- player update ----------
function updatePlayer(){
  if(readyTimer>0){readyTimer--;return;}
  if(deathTimer>0){if(--deathTimer<=0){
      if(lives<=0){state='gameover';introTimer=200;}
      else{readyTimer=110;player.x=112;player.y=252;player.alive=true;player.dual=false;}
    }return;}
  if(player.capturePull){
    const b=player.capturingBoss;
    if(!b||b.state!=='beam'){player.capturePull=false;return;}
    player.x+=(b.x-player.x)*0.08;player.y-=1.6;
    if(player.y<=b.y+16){
      b.captive={x:player.x,y:player.y,state:'follow',fireTimer:90};
      player.capturePull=false;killPlayer(false);
    }
    return;
  }
  const sp=2.2;
  if(keys.ArrowLeft||keys.a||keys.A)player.x-=sp;
  if(keys.ArrowRight||keys.d||keys.D)player.x+=sp;
  player.x=Math.max(12,Math.min(212,player.x));
}
function killPlayer(ramMed){
  if(!player.alive)return;
  boom(player.x,player.y,true);sPlayerDie();
  player.alive=false;player.dual=false;deathTimer=70;lives--;
}

// ---------- combat ----------
function escortCount(e){return e.escorts?e.escorts.filter(x=>x.state==='dive'||x.state==='beam').length:0;}
function destroyEnemy(e,idx,byPlayer){
  enemies.splice(idx,1);
  if(e.escortOf&&e.escortOf.escorts)e.escortOf.escorts=e.escortOf.escorts.filter(x=>x!==e);
  boom(e.x,e.y,e.type==='boss');
  if(e.captive){ // boss killed while holding captive
    if(e.state==='dive'||e.state==='beam'){freed.push({x:e.captive.x,y:e.captive.y});}
    else{boom(e.captive.x,e.captive.y,false);} // captive destroyed with boss
    e.captive=null;
  }
  if(byPlayer){
    hits++;
    let pts;
    const diving=(e.state==='dive'||e.state==='beam');
    if(e.type==='zako')pts=diving?100:50;
    else if(e.type==='goei')pts=diving?160:80;
    else{const n=escortCount(e);pts=diving?(n===2?1600:n===1?800:400):150;}
    if(e.state==='chal')pts=100;
    addScore(pts);
    // killing a boss with escorts destroys the escorts too
    if(e.type==='boss'&&diving&&e.escorts){
      for(const g of e.escorts.slice()){
        const gi=enemies.indexOf(g);
        if(gi>=0){addScore(160);destroyEnemy(g,gi,false);}
      }
    }
  }
}
function updateCombat(){
  // player shots
  for(let i=pShots.length-1;i>=0;i--){
    const b=pShots[i];b.y-=4.2;
    if(b.y<-8){pShots.splice(i,1);continue;}
    let done=false;
    for(let j=enemies.length-1;j>=0&&!done;j--){
      const e=enemies[j];
      if(e.state==='enter'&&e.age<e.delay)continue;
      const hw=e.type==='boss'?8:7,hh=e.type==='boss'?6:5;
      if(overlap(b.x,b.y,1,4,e.x,e.y,hw,hh)){
        if(e.type==='boss'&&e.hp>1){e.hp--;e.damaged=true;sBossHit();hits++;}
        else{sHit();destroyEnemy(e,j,true);}
        pShots.splice(i,1);done=true;
      }else if(e.captive&&overlap(b.x,b.y,1,4,e.captive.x,e.captive.y,6,7)){
        boom(e.captive.x,e.captive.y,false);e.captive=null;sHit();hits++;addScore(100);
        pShots.splice(i,1);done=true;
      }
    }
  }
  // enemy shots vs player
  if(player.alive&&readyTimer<=0&&deathTimer<=0&&!player.capturePull){
    for(let i=eShots.length-1;i>=0;i--){
      const b=eShots[i];b.x+=b.vx;b.y+=b.vy;
      if(b.y>H+8||b.y<-8||b.x<-8||b.x>W+8){eShots.splice(i,1);continue;}
      const halves=player.dual?[-8,8]:[0];
      for(const h of halves){
        if(overlap(b.x,b.y,2,3,player.x+h,player.y,5,7)){
          eShots.splice(i,1);
          if(player.dual){player.dual=false;boom(player.x+h,player.y,true);sPlayerDie();}
          else killPlayer();
          break;
        }
      }
    }
  }
  // ram collisions
  if(player.alive&&readyTimer<=0&&deathTimer<=0&&!player.capturePull){
    outer:
    for(let j=enemies.length-1;j>=0;j--){
      const e=enemies[j];
      if(e.state!=='dive'&&e.state!=='beam'&&e.state!=='chal')continue;
      if(e.age<(e.delay||0))continue;
      const hw=e.type==='boss'?8:7,hh=e.type==='boss'?6:5;
      const halves=player.dual?[-8,8]:[0];
      for(const h of halves){
        if(overlap(player.x+h,player.y,5,7,e.x,e.y,hw,hh)){
          if(e.state==='chal'){destroyEnemy(e,j,true);}else{destroyEnemy(e,j,false);}
          if(player.dual){player.dual=false;boom(player.x+h,player.y,true);sPlayerDie();}
          else killPlayer();
          break outer;
        }
      }
      if(e.captive&&overlap(player.x,player.y,5,7,e.captive.x,e.captive.y,6,7)){
        boom(e.captive.x,e.captive.y,false);e.captive=null;
        if(player.dual){player.dual=false;boom(player.x,player.y,true);sPlayerDie();}else killPlayer();
        break;
      }
    }
  }
  // freed captive docking -> dual fighter
  for(let i=freed.length-1;i>=0;i--){
    const f=freed[i];f.y+=1.8;f.x+=(player.x-f.x)*0.06;
    if(player.alive&&readyTimer<=0&&deathTimer<=0&&!player.dual&&f.y>=player.y-16&&Math.abs(f.x-player.x)<10){
      player.dual=true;freed.splice(i,1);sDock();
    }else if(f.y>H+16){freed.splice(i,1);}
  }
}

// ---------- challenging-stage bookkeeping ----------
function updateChallenging(){
  for(let w=0;w<5;w++){
    const aliveW=enemies.some(e=>e.state==='chal'&&e.wave===w);
    if(!aliveW&&chalWaves[w].dead+chalWaves[w].exit===8&&!chalWaves[w].bonus){
      chalWaves[w].bonus=true;
      if(chalWaves[w].dead===8){addScore(1000);chalWaves[w].paid1000=true;}
    }
  }
  if(enemies.length===0){
    const perfect=chalWaves.every(w=>w.dead===8);
    chalBonus=(perfect?10000:0);
    if(perfect)addScore(10000);
    state='chalResults';resTimer=320;
  }
}

// ---------- main update ----------
function update(){
  tick++;updateStars();updateExpls();
  if(paused||state!=='play')return;
  if(readyTimer>0||deathTimer>0){updatePlayer();updateEnemies();updateCombat();return;}
  updatePlayer();
  updateEnemies();
  if(!challenging)updateBeamCapture();
  updateCombat();
  if(challenging)updateChallenging();
  if(!challenging&&enemies.length===0&&allEntered){
    if(++clearTimer>70){clearTimer=0;nextStage();}
  }
}

// ---------- rendering ----------
function drawStars(){for(const s of stars){ctx.globalAlpha=0.45+0.55*Math.abs(Math.sin(tick*0.05+s.ph));ctx.fillStyle=s.c;ctx.fillRect(Math.round(s.x),Math.round(s.y),1,1);}ctx.globalAlpha=1;}
function drawHUD(){
  text('1UP',16,10,'#ff3322',8);
  text(String(score).padStart(6,' '),16,20,'#fff',8);
  text('HIGH SCORE',112,10,'#ff3322',8,'center');
  text(String(high).padStart(6,' '),112,20,'#fff',8,'center');
  for(let i=0;i<lives-1;i++)drawSprite(SP.player,18+i*14,278);
  // stage flags (denominations 1,5,10,20,30,50,70)
