    ctx.fillStyle='#fff';ctx.fillRect(x,270,1,10);
    ctx.fillStyle=c;ctx.beginPath();ctx.moveTo(x+1,270);ctx.lineTo(x+8,272);ctx.lineTo(x+1,275);ctx.fill();
