// ---------- state timers (run even while 'paused' is handled in update) ----------
function tickStates(){
  if(state==='stageIntro'&&--introTimer<=0){state='play';}
  else if(state==='gameover'&&--introTimer<=0){state='results';resTimer=340;}
  else if(state==='results'&&--resTimer<=0){state='title';}
  else if(state==='chalResults'&&--resTimer<=0){nextStage();}
}

// ---------- fixed-timestep loop ----------
let acc=0,last=performance.now();
function frame(now){
  acc+=Math.min(now-last,100);last=now;
  while(acc>=DT){
    if(!paused){tickStates();update();}
    acc-=DT;
  }
  render();
  requestAnimationFrame(frame);
}
